import '../models/materi_content.dart';

/// Materi PPKn SMP Kelas 7.
const List<MateriSection> materiKelas7 = <MateriSection>[
  MateriSection(
    id: 'kelas7-materi-1',
    number: 1,
    title: 'Sejarah Kelahiran Pancasila',
    summary: 'Pancasila tidak lahir dalam semalam. Ia adalah hasil dari perenungan panjang, perdebatan gagasan, dan pengorbanan ego sektoral demi berdirinya sebuah negara yang merdeka dan bersatu. Berikut adalah uraian detail proses kelahiran Pancasila.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.heading, 'Latar Belakang Perumusan (Masa BPUPK)'),
      MateriBlock(MateriBlockType.numberedItem, '1. Kondisi Kekalahan Jepang dalam Perang Pasifik'),
      MateriBlock(MateriBlockType.paragraph, 'Memasuki tahun 1944, posisi tentara Jepang dalam Perang Asia Pasifik (Perang Dunia II) semakin terdesak oleh pasukan Sekutu. Banyak wilayah kekuasaan Jepang yang jatuh. Menyadari posisi yang melemah, Perdana Menteri Jepang saat itu, Kuniaki Koiso, memberikan "Janji Kemerdekaan" kepada bangsa Indonesia pada tanggal 7 September 1944. Tujuannya murni taktik politik: agar rakyat Indonesia mau membantu Jepang melawan Sekutu.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Pembentukan BPUPK (Dokuritsu Junbi Cosakai)'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai realisasi janji tersebut, pada tanggal 1 Maret 1945, Letnan Jenderal Kumakichi Harada mengumumkan pembentukan Badan Penyelidik Usaha-Usaha Persiapan Kemerdekaan (BPUPK).'),
      MateriBlock(MateriBlockType.bullet, 'Peresmian: BPUPK baru diresmikan susunannya pada tanggal 29 April 1945 (bertepatan dengan hari ulang tahun Kaisar Hirohito).'),
      MateriBlock(MateriBlockType.heading, 'Struktur Organisasi:'),
      MateriBlock(MateriBlockType.bullet, 'Ketua: Dr. K.R.T. Radjiman Wedyodiningrat'),
      MateriBlock(MateriBlockType.bullet, 'Ketua Muda (Wakil): Ichibangase Yosio (Orang Jepang) dan Raden Pandji Soeroso.'),
      MateriBlock(MateriBlockType.bullet, 'Anggota: Berjumlah 67 orang (60 tokoh Indonesia dan 7 orang Jepang yang berstatus anggota istimewa tanpa hak suara).'),
      MateriBlock(MateriBlockType.bullet, 'Tujuan: Mempelajari dan menyelidiki hal-hal krusial terkait pembentukan negara Indonesia merdeka, mulai dari aspek politik, ekonomi, hukum, hingga dasar negara.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Sidang Pertama BPUPK (29 Mei - 1 Juni 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Sidang ini dilaksanakan di Gedung Chuo Sangi In (sekarang Gedung Pancasila di Jakarta). Sidang dibuka dengan sebuah pertanyaan sangat mendasar dan krusial dari sang Ketua, dr. Radjiman: "Di atas dasar apakah Negara Indonesia Merdeka ini akan didirikan?" Pertanyaan inilah yang memicu para tokoh bangsa untuk memeras otak dan berpidato mengemukakan gagasannya.'),
      MateriBlock(MateriBlockType.heading, 'Tokoh-Tokoh Perumus Pancasila dan Dinamikanya'),
      MateriBlock(MateriBlockType.paragraph, 'Selama sidang pertama BPUPK, ada puluhan tokoh yang berbicara, namun ada tiga tokoh utama yang secara komprehensif merumuskan rancangan dasar negara:'),
      MateriBlock(MateriBlockType.numberedItem, '1. Mr. Mohammad Yamin (29 Mei 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Yamin adalah tokoh pertama yang berpidato. Ia menekankan bahwa dasar negara Indonesia harus berasal dari peradaban dan kebudayaan Indonesia sendiri, bukan meniru luar negeri. Uniknya, Yamin mengaku memberikan usulan dasar negara berupa Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, dan Kesejahteraan Rakyat'),
      MateriBlock(MateriBlockType.bullet, 'Fakta Sejarah yang Diluruskan: Berbeda dengan buku teks lama, Yamin ternyata dalam pidatonya tidak menyampaikan rumusan lima asas (Peri Kebangsaan dll tersebut).'),
      MateriBlock(MateriBlockType.bullet, 'Isi Pidato Asli: Pidato Yamin (berjudul Asas dan Dasar Negara Kebangsaan Republik Indonesia) berfokus pada bentuk negara dan tinjauan sejarah. Ia menelusuri kejayaan Sriwijaya dan Majapahit sebagai bukti bahwa bangsa Indonesia punya tradisi ketatanegaraan yang kuat. Ia menolak bentuk negara kerajaan atau feodal, dan secara tegas mengusulkan agar Indonesia merdeka berbentuk Negara Kesatuan (Republik) yang berakar pada peradaban Timur, bukan meniru demokrasi Barat.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Prof. Dr. Mr. Soepomo (31 Mei 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai pakar hukum adat, Soepomo menyampaikan gagasan tentang struktur sosial bangsa Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Teori Negara Integralistik: Soepomo menolak paham individualisme (seperti Eropa) dan paham komunisme (seperti Soviet). Ia mengusulkan "Negara Kekeluargaan" (Integralistik).'),
      MateriBlock(MateriBlockType.bullet, 'Inti Gagasan: Negara tidak memihak pada satu golongan atau mayoritas, melainkan negara bersatu dengan seluruh rakyatnya. Pemimpin dan rakyat ibarat bapak dan anak dalam satu keluarga besar yang mengedepankan persatuan, semangat gotong royong, dan musyawarah.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Ir. Soekarno (1 Juni 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Soekarno adalah tokoh yang akhirnya berhasil menjawab pertanyaan dr. Radjiman secara sistematis, konseptual, dan merumuskan dasar negara secara konkret.'),
      MateriBlock(MateriBlockType.bullet, 'Lahirnya Istilah Pancasila: Berpidato tanpa teks, Soekarno mengemukakan lima prinsip dasar negara. Atas petunjuk seorang teman ahli bahasa, ia menamakannya Pancasila.'),
      MateriBlock(MateriBlockType.heading, 'Lima Dasar Soekarno:'),
      MateriBlock(MateriBlockType.bullet, 'Kebangsaan Indonesia (bukan chauvinisme, melainkan nasionalisme yang kuat)'),
      MateriBlock(MateriBlockType.bullet, 'Internasionalisme atau Perikemanusiaan (nasionalisme yang diimbangi persaudaraan dunia)'),
      MateriBlock(MateriBlockType.bullet, 'Mufakat atau Demokrasi (perwakilan politik bagi seluruh golongan)'),
      MateriBlock(MateriBlockType.bullet, 'Kesejahteraan Sosial (keadilan ekonomi, tidak ada kemiskinan di alam merdeka)'),
      MateriBlock(MateriBlockType.bullet, 'Ketuhanan yang Berkebudayaan (Ketuhanan yang saling menghormati antar umat beragama)'),
      MateriBlock(MateriBlockType.bullet, 'Hari pidato inilah yang ditetapkan sebagai tonggak Hari Lahir Pancasila.'),
      MateriBlock(MateriBlockType.numberedItem, '4. Masa Reses dan Pembentukan Panitia Sembilan'),
      MateriBlock(MateriBlockType.paragraph, 'Hingga akhir sidang 1 Juni, belum ada kesepakatan satu pun mengenai dasar negara karena adanya perdebatan tajam antara Golongan Nasionalis Sekuler (ingin negara kebangsaan) dan Golongan Islam (ingin negara berdasarkan syariat Islam). BPUPK kemudian memasuki masa reses, untuk memecahkan kebuntuan, dibentuklah panitia kecil beranggotakan 9 orang yang diketuai Ir. Soekarno. Anggotanya: Soekarno, Moh. Hatta, M. Yamin, A.A. Maramis, Achmad Soebardjo (Nasionalis) dan KH Wahid Hasyim, Kahar Muzakkir, Haji Agus Salim, Abikusno Tjokrosujoso (Islam).'),
      MateriBlock(MateriBlockType.numberedItem, '5. Lahirnya Piagam Jakarta (22 Juni 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Panitia Sembilan bersidang dengan alot namun akhirnya menghasilkan dokumen kompromi bersejarah yang disebut Jakarta Charter (Piagam Jakarta). Dokumen ini menyatukan dua golongan tersebut. Rumusan dasar negara di dalamnya adalah:'),
      MateriBlock(MateriBlockType.bullet, 'Ketuhanan, dengan kewajiban menjalankan syari\'at Islam bagi pemeluk-pemeluknya.'),
      MateriBlock(MateriBlockType.bullet, 'Kemanusiaan yang adil dan beradab.'),
      MateriBlock(MateriBlockType.bullet, 'Persatuan Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan.'),
      MateriBlock(MateriBlockType.bullet, 'Keadilan sosial bagi seluruh rakyat Indonesia.'),
      MateriBlock(MateriBlockType.heading, 'Proses Pengesahan Pancasila (Masa PPKI)'),
      MateriBlock(MateriBlockType.numberedItem, '1. Pembubaran BPUPK dan Pembentukan PPKI'),
      MateriBlock(MateriBlockType.paragraph, 'Setelah tugas BPUPK menyusun rancangan UUD selesai, Jepang membubarkannya dan menggantinya dengan PPKI (Dokuritsu Junbi Inkai) pada tanggal 7 Agustus 1945, yang diketuai oleh Ir. Soekarno dan wakil Moh. Hatta. Keanggotaan PPKI murni orang Indonesia, menandakan kemerdekaan sepenuhnya di tangan bangsa Indonesia.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Krisis Sore Hari, 17 Agustus 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Setelah Proklamasi Kemerdekaan dibacakan pada pagi hari 17 Agustus 1945, pada sore harinya, Moh. Hatta didatangi oleh seorang perwira Angkatan Laut Jepang. Perwira tersebut menyampaikan aspirasi dari perwakilan rakyat Indonesia Bagian Timur (seperti Maluku, Minahasa, dll yang mayoritas beragama Kristen/Katolik), mereka merasa keberatan dengan tujuh kata dalam sila pertama Piagam Jakarta: "dengan kewajiban menjalankan syari\'at Islam bagi pemeluk-pemeluknya." Mereka menyatakan: "Jika tujuh kata itu tidak dihilangkan, kami lebih baik berdiri di luar Republik Indonesia."'),
      MateriBlock(MateriBlockType.numberedItem, '3. Lobi Pagi Hari yang Menentukan Nasib Bangsa (18 Agustus 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Menyadari bahwa Republik yang baru berumur 1 hari ini terancam pecah, pada pagi hari tanggal 18 Agustus 1945 (sebelum sidang perdana PPKI dimulai), Moh. Hatta berinisiatif mengumpulkan tokoh-tokoh Islam, yaitu: Ki Bagus Hadikusumo, KH Wahid Hasyim, Mr. Kasman Singodimedjo, dan Teuku Mohammad Hasan. Hatta melobi mereka untuk memikirkan keutuhan Indonesia yang terbentang dari Sabang sampai Merauke. Melalui proses diskusi yang mencerminkan jiwa kebesaran, toleransi yang tinggi, dan semangat persatuan, tokoh-tokoh Islam tersebut dengan ikhlas setuju untuk menghapus tujuh kata tersebut.'),
      MateriBlock(MateriBlockType.numberedItem, '4. Sidang PPKI 18 Agustus 1945: Pengesahan UUD 1945 dan Pancasila'),
      MateriBlock(MateriBlockType.paragraph, 'Pada sidang PPKI tanggal 18 Agustus 1945, keputusan-keputusan penting diambil, di antaranya:'),
      MateriBlock(MateriBlockType.bullet, 'Mengesahkan Undang-Undang Dasar (UUD 1945).'),
      MateriBlock(MateriBlockType.bullet, 'Memilih Ir. Soekarno sebagai Presiden dan Moh. Hatta sebagai Wakil Presiden.'),
      MateriBlock(MateriBlockType.bullet, 'Membentuk Komite Nasional Indonesia Pusat (KNIP) untuk membantu tugas Presiden.'),
      MateriBlock(MateriBlockType.paragraph, 'Di dalam Pembukaan UUD 1945 Alinea Keempat yang disahkan pada hari itu, tercantum rumusan dasar negara yang final, sah, dan berlaku hingga detik ini:'),
      MateriBlock(MateriBlockType.bullet, 'Ketuhanan Yang Maha Esa (hasil revisi dari Piagam Jakarta)'),
      MateriBlock(MateriBlockType.bullet, 'Kemanusiaan yang adil dan beradab'),
      MateriBlock(MateriBlockType.bullet, 'Persatuan Indonesia'),
      MateriBlock(MateriBlockType.bullet, 'Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan'),
      MateriBlock(MateriBlockType.bullet, 'Keadilan sosial bagi seluruh rakyat Indonesia.'),
      MateriBlock(MateriBlockType.paragraph, 'Dengan disahkannya UUD 1945, maka secara hukum tata negara, Pancasila resmi menjadi Dasar Negara Republik Indonesia. Kunci dari pengesahan ini adalah semangat Gotong Royong, Musyawarah, dan Toleransi dari para pendiri bangsa (Founding Fathers).'),
    ],
  ),
  MateriSection(
    id: 'kelas7-materi-2',
    number: 2,
    title: 'Penerapan Nilai Pancasila',
    summary: 'Penerapan Pancasila berarti mengubah teks yang dibacakan setiap upacara hari Senin menjadi tindakan nyata di kehidupan sehari-hari, mulai dari ruang kelas, tempat berkumpul, hingga saat bermain media sosial. Pancasila tidak diciptakan hanya untuk dihafalkan agar lulus ujian Pendidikan Pancasila, melainkan sebagai "buku panduan" atau kompas yang mengarahkan cara pelajar berpikir, berbicara, dan bertindak agar menjadi pribadi yang berkarakter. Bayangkan Pancasila sebagai sistem operasi (OS) atau software di dalam sebuah ponsel cerdas. Membaca dan menghafal sila-sila Pancasila sama seperti mengunduh software tersebut. Sedangkan menerapkan Pancasila adalah mengaktifkan dan menjalankan software itu agar ponsel berfungsi dengan baik, aman dari virus (pengaruh buruk), dan bermanfaat bagi penggunanya. Jika hanya diunduh tanpa dijalankan, software tersebut tidak ada gunanya.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.paragraph, 'Bentuk Nyata Penerapan Pancasila di Dunia Remaja yaitu sebagai filter informasi dan tren, panduan bergaul dan berteman, dan cara menyelesaikan masalah (resolusi konflik). Secara sederhana, penerapan Pancasila terjadi ketika sikap saling menghargai, adil, jujur, dan beradab sudah menjadi kebiasaan atau refleks alami sehari-hari, tanpa perlu diawasi oleh guru atau orang tua.'),
      MateriBlock(MateriBlockType.heading, 'Penerapan Sila Pertama: Ketuhanan Yang Maha Esa'),
      MateriBlock(MateriBlockType.heading, 'Sila pertama Pancasila yang berbunyi "Ketuhanan Yang Maha Esa" disimbolkan dengan Bintang Emas berlatar belakang hitam. Bagi seorang pelajar, lambang ini bukan sekadar gambar yang wajib dipajang di atas papan tulis kelas, melainkan sebuah "kompas" atau penunjuk arah dalam menjalani kehidupan sehari-hari. Simbol bintang emas ini bermakna sebagai cahaya kerohanian yang diturunkan oleh Tuhan kepada setiap manusia untuk menerangi jalan kehidupannya.'),
      MateriBlock(MateriBlockType.paragraph, 'Pernahkah terlintas pertanyaan, mengapa "Ketuhanan Yang Maha Esa" diletakkan di urutan nomor satu, bukan nomor tiga atau nomor lima? Jawabannya adalah karena nilai Ketuhanan merupakan "Pondasi Utama" atau dasar moral bagi keempat sila lainnya.'),
      MateriBlock(MateriBlockType.bullet, 'Sila kedua (Kemanusiaan) tidak akan berjalan baik jika seseorang tidak memiliki rasa takut pada Tuhan.'),
      MateriBlock(MateriBlockType.bullet, 'Sila ketiga (Persatuan) akan hancur lebur jika orang-orang beragama justru saling menyebarkan kebencian dan bermusuhan.'),
      MateriBlock(MateriBlockType.bullet, 'Sila keempat (Kerakyatan) akan berujung pada kelicikan dan korupsi jika para pemimpin dan rakyatnya tidak memiliki dasar moral keagamaan.'),
      MateriBlock(MateriBlockType.bullet, 'Sila kelima (Keadilan) mustahil tercapai jika manusia tidak diajarkan oleh agamanya untuk bersikap jujur dan adil kepada sesama.'),
      MateriBlock(MateriBlockType.paragraph, 'Dengan memahami dan menerapkan Sila Pertama dalam kehidupan, para pelajar tidak hanya sekadar mempraktikkan materi pelajaran PPKn untuk mendapatkan nilai bagus. Lebih jauh dari itu, mereka sedang membangun diri menjadi pribadi yang berintegritas, peduli, penuh kasih sayang, dan berprinsip teguh. Mulailah dari hal-hal kecil hari ini: niatkan kegiatan belajar sebagai bentuk ibadah, hargai teman-teman di sekitar, dan jadilah "Bintang Emas" yang terus memancarkan energi positif serta kedamaian di lingkungan sekola'),
      MateriBlock(MateriBlockType.paragraph, 'Di usia Sekolah Menengah Pertama (SMP), seorang remaja sedang berada di masa transisi yang seru sekaligus menantang. Di masa ini, para pelajar mulai memiliki banyak teman dari berbagai latar belakang, mulai aktif berinteraksi di media sosial, dan mulai mencari jati diri. Di sinilah nilai-nilai sila pertama berperan sangat penting agar generasi muda bisa tumbuh menjadi individu yang berkarakter, toleran, dan memiliki pondasi moral yang kuat dalam menghadapi arus pergaulan.'),
      MateriBlock(MateriBlockType.paragraph, 'Berikut adalah uraian lengkap mengenai bagaimana penerapan sila pertama Pancasila dalam kehidupan sehari-hari sebagai seorang pelajar SMP.'),
      MateriBlock(MateriBlockType.numberedItem, '1. Makna Sila Pertama: Jauh Lebih dari Sekadar Identitas di KTP'),
      MateriBlock(MateriBlockType.paragraph, 'Banyak orang mengira bahwa sila pertama hanya sekadar urusan apa agama yang kelak tertulis di Kartu Pelajar atau Kartu Tanda Penduduk (KTP). Padahal, maknanya jauh lebih dalam dan luas dari itu. Sila pertama mengajarkan bangsa Indonesia tentang Keyakinan dan Ketakwaan. Artinya, seluruh rakyat Indonesia percaya bahwa Tuhan itu ada, dan setiap individu berusaha menjalankan perintah-Nya serta menjauhi larangan-Nya sesuai dengan ajaran agama atau kepercayaan masing-masing.'),
      MateriBlock(MateriBlockType.paragraph, 'Bagi anak SMP, bentuk ketakwaan ini tidak harus selalu berupa ibadah yang berat. Menjadi remaja yang bertakwa berarti memiliki kesadaran penuh bahwa setiap tindakan yang dilakukan selalu dilihat oleh Tuhan. Kesadaran inilah yang akan membuat seseorang berpikir dua kali sebelum melakukan hal-hal negatif. Contohnya, rasa takut kepada Tuhan akan mencegah niat untuk mencontek saat ulangan, berbohong kepada orang tua, atau menindas teman (bullying). Agama dan kepercayaan menjadi rem alami yang menahan hati nurani dari perbuatan buruk.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Penerapan di Lingkungan Sekolah: Menjunjung Tinggi Toleransi'),
      MateriBlock(MateriBlockType.paragraph, 'Sekolah adalah miniatur masyarakat, tempat bertemunya berbagai macam karakter dan latar belakang keluarga. Di sekolah negeri maupun swasta umum, pasti akan ada teman-teman yang memiliki keyakinan berbeda. Di sinilah ujian nyata dari penerapan sila pertama terjadi.'),
      MateriBlock(MateriBlockType.bullet, 'Berdoa Sebelum dan Sesudah Belajar: Ini adalah hal paling sederhana namun sering dianggap remeh. Saat ketua kelas memimpin doa, sikap yang benar adalah berdoa dengan sungguh-sungguh menurut ajaran agama masing-masing. Sangat tidak pantas jika waktu berdoa justru digunakan untuk mengobrol atau bermain alat tulis. Doa adalah bentuk permohonan kepada Tuhan agar ilmu yang dipelajari hari itu bisa dipahami dengan baik dan membawa manfaat di masa depan.'),
      MateriBlock(MateriBlockType.bullet, 'Menghargai Teman yang Sedang Beribadah: Bayangkan suasana sedang asyik bermain basket di lapangan saat jam istirahat sore, lalu ada seorang teman yang meminta izin untuk menunaikan ibadah salat Asar. Sikap yang mencerminkan sila pertama adalah mempersilakan teman tersebut beribadah, atau bahkan membantunya menjaga barang bawaannya agar ia bisa beribadah dengan tenang. Sangat dilarang untuk mengejek, mengolok-olok, atau memaksanya terus bermain.'),
      MateriBlock(MateriBlockType.bullet, 'Berteman Tanpa Memandang Latar Belakang Agama: Jalinlah pertemanan dengan siapa saja tanpa melihat apa agamanya. Tidak perlu membuat kelompok atau "geng" yang hanya berisi orang-orang dari agama yang sama. Keberagaman justru membuat suasana pertemanan menjadi lebih berwarna. Lewat teman beda agama, ada banyak hal baru yang bisa dipelajari, seperti tradisi hari raya, budaya, dan kebiasaan baik dari ajaran lain.'),
      MateriBlock(MateriBlockType.bullet, 'Toleransi Saat Hari Raya atau Bulan Puasa: Jika kebetulan umat muslim sedang menjalankan ibadah puasa Ramadan, wujud toleransi yang bisa dilakukan adalah tidak makan atau minum dengan sengaja tepat di hadapan mereka. Sebaliknya, mereka yang berpuasa juga tidak boleh egois dengan memaksa kantin sekolah ditutup sepenuhnya, karena ada siswa lain yang tidak berpuasa dan tetap membutuhkan makan siang. Inilah indahnya saling menjaga perasaan dan menghargai.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Penerapan di Lingkungan Rumah: Membangun Kebiasaan Baik'),
      MateriBlock(MateriBlockType.paragraph, 'Keluarga adalah tempat pertama kali seseorang belajar tentang agama, budi pekerti, dan Tuhan. Sebagai anak SMP yang sudah beranjak dewasa, kemandirian dalam urusan ibadah seharusnya sudah mulai tumbuh dan terlihat nyata.'),
      MateriBlock(MateriBlockType.bullet, 'Ibadah Tanpa Harus Disuruh: Saat masih duduk di bangku Sekolah Dasar (SD), mungkin orang tua harus terus-menerus mengingatkan atau merayu anaknya agar mau beribadah. Di masa SMP, sudah saatnya kedewasaan ditunjukkan dengan melaksanakan ibadah tepat waktu atas kesadaran sendiri. Ini adalah bentuk tanggung jawab pribadi manusia kepada Sang Pencipta.'),
      MateriBlock(MateriBlockType.bullet, 'Mensyukuri Nikmat di Dalam Keluarga: Mengeluh karena makanan di meja makan kurang enak, atau marah besar karena orang tua belum mampu membelikan barang yang sedang tren, merupakan contoh sikap kurang bersyukur. Sila pertama mengajarkan umat manusia untuk selalu bersyukur atas apa pun rezeki dan keadaan yang diberikan Tuhan melalui perantara orang tua. Bersyukur akan membuat hidup terasa lebih tenang, damai, dan bahagia.'),
      MateriBlock(MateriBlockType.bullet, 'Menghormati Orang Tua sebagai Perintah Agama: Semua agama yang diakui di Indonesia (Islam, Kristen, Katolik, Hindu, Buddha, maupun Khonghucu), mengajarkan umatnya untuk berbakti kepada orang tua. Jadi, ketika seorang anak membantu ibunya menyapu rumah atau bertutur kata sopan kepada ayahnya, itu bukan sekadar menunjukkan sopan santun, tetapi juga sedang menjalankan perintah Tuhan dengan sungguh-sungguh.'),
      MateriBlock(MateriBlockType.numberedItem, '4. Penerapan di Dunia Digital (Media Sosial): Bijak Berkomentar, Jaga Toleransi'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai Generasi Z (Gen-Z), sebagian besar waktu luang pelajar saat ini dihabiskan di dunia maya, entah itu berselancar di TikTok, Instagram, Twitter, atau bermain game online. Di ruang digital yang tanpa batas dan seolah tanpa aturan ini, penerapan sila pertama justru sangat diuji.'),
      MateriBlock(MateriBlockType.bullet, 'Hindari Candaan yang Menyinggung SARA: Terkadang, demi terlihat keren atau lucu di komunitas online, seseorang membuat meme atau candaan yang merendahkan simbol agama tertentu. Ini adalah pelanggaran keras terhadap nilai-nilai Pancasila. Menghina Tuhan, kitab suci, nabi, atau ajaran agama lain bukanlah hal yang lucu sama sekali. Jadilah pengguna internet (netizen) yang cerdas, beradab, dan memikirkan dampak dari setiap ketikan.'),
      MateriBlock(MateriBlockType.bullet, 'Tidak Memaksakan Keyakinan di Kolom Komentar: Saat melihat konten yang berisi pandangan agama yang berbeda, tidak perlu memaksakan pendapat pribadi di kolom komentar sampai memicu pertengkaran (war comment). Negara Indonesia memberikan kebebasan beragama, jadi hargailah hak dan ruang digital orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Berbagi Kebaikan: Gunakan media sosial untuk menyebarkan nilai-nilai positif yang diajarkan oleh agama. Misalnya, membuat kutipan tentang semangat menuntut ilmu, pentingnya menjaga kebersihan, pentingnya kejujuran, atau sekadar membagikan pesan perdamaian.'),
      MateriBlock(MateriBlockType.numberedItem, '5. Menghindari Bahaya Sikap Fanatisme Sempit'),
      MateriBlock(MateriBlockType.paragraph, 'Satu hal krusial yang harus dihindari oleh anak usia SMP adalah jebakan "fanatisme sempit". Fanatisme sempit adalah sebuah sikap merasa bahwa agama atau keyakinan yang dianutnya adalah yang paling benar secara mutlak, sehingga ia merasa berhak merendahkan, menghina, atau bahkan membenci penganut agama lain. Negara Kesatuan Republik Indonesia didirikan di atas keberagaman suku, budaya, dan agama. Para pendiri bangsa, yang juga berasal dari berbagai latar belakang agama yang berbeda, sepakat untuk bersatu demi kemerdekaan. Jika ada yang membenci orang lain hanya karena agamanya berbeda, itu berarti orang tersebut mengkhianati perjuangan para pahlawan. Meyakini bahwa agama yang dipeluk adalah agama yang paling benar di dalam hati adalah kewajiban umat beragama, namun memaksakan keyakinan tersebut kepada orang lain dan merendahkan agama lain adalah tindakan intoleran yang bisa memecah belah persatuan.'),
      MateriBlock(MateriBlockType.heading, 'Penerapan Sila Ke Dua Kemanusiaan yang Adil dan Beradab'),
      MateriBlock(MateriBlockType.paragraph, 'Memahami sila kedua membutuhkan penguraian dari tiga kata kuncinya. Pertama, Kemanusiaan, yang berarti kesadaran penuh bahwa setiap individu di muka bumi ini memiliki hak, martabat, perasaan, dan kebebasan yang sama sebagai manusia ciptaan Tuhan. Tidak ada manusia yang derajatnya lebih rendah hanya karena perbedaan fisik atau latar belakang keluarga. Kedua, Adil, yang berarti memperlakukan semua orang dengan porsi yang proporsional dan rasional. Sikap adil menuntut seseorang untuk tidak membeda-bedakan teman berdasarkan status sosial, tingkat ekonomi keluarga, kepintaran, maupun kondisi fisik. Ketiga, Beradab, yang merujuk pada kepemilikan budi pekerti, etika, tata krama, dan sopan santun saat berinteraksi. Manusia yang beradab tahu bagaimana cara menempatkan diri, menjaga lisannya agar tidak menyakiti orang lain, dan menghormati norma-norma yang berlaku di masyarakat.'),
      MateriBlock(MateriBlockType.bullet, 'Menghapus Budaya Perundungan (Bullying) di Sekolah'),
      MateriBlock(MateriBlockType.paragraph, 'Penerapan paling krusial dari sila kedua di usia SMP adalah penerapan prinsip toleransi nol (zero tolerance) terhadap perundungan atau bullying. Masa SMP sering kali menjadi fase di mana remaja mencari pengakuan dari kelompoknya, yang sayangnya kerap dilakukan dengan cara menjatuhkan orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Menolak Kekerasan Verbal: Memanggil teman dengan nama orang tuanya sebagai bahan candaan, memberikan julukan yang merendahkan bentuk tubuh (body shaming), atau melontarkan hinaan rasial adalah pelanggaran berat terhadap nilai kemanusiaan. Candaan hanya berlaku jika kedua belah pihak merasa senang; jika salah satu pihak merasa sakit hati, itu adalah penindasan.'),
      MateriBlock(MateriBlockType.bullet, 'Mencegah Kekerasan Relasional: Mengucilkan seorang siswa dari pergaulan, membuat grup obrolan tersembunyi untuk membicarakan keburukan teman sekelas, atau menghasut orang lain agar ikut membenci seseorang merupakan tindakan yang tidak beradab. Sila kedua mengajarkan pelajar untuk merangkul teman yang tersisih, bukan malah ikut menjauhinya.'),
      MateriBlock(MateriBlockType.bullet, 'Keberanian Membela Korban: Jika ada teman yang menjadi korban ketidakadilan, difitnah, atau diperlakukan sewenang-wenang, pelajar yang memiliki nilai Pancasila akan berani bersuara dan membelanya. Diam saat melihat penindasan terjadi sama artinya dengan ikut membiarkan ketidakadilan tersebut merajalela.'),
      MateriBlock(MateriBlockType.bullet, 'Keadilan dalam Kehidupan Akademik dan Sosial'),
      MateriBlock(MateriBlockType.paragraph, 'Sikap adil tidak hanya berlaku di ruang sidang atau pemerintahan, tetapi juga di dalam kelas. Saat guru memberikan tugas kelompok, penerapan sila kedua sangat diuji. Membagi tugas secara merata sesuai porsi dan kemampuan masing-masing anggota adalah wujud keadilan yang nyata. Sangat tidak adil dan tidak beradab jika membiarkan satu atau dua orang anggota mengerjakan seluruh tugas sementara anggota lainnya asyik bermain game atau mengobrol, lalu sekadar "numpang nama" saat tugas dikumpulkan.'),
      MateriBlock(MateriBlockType.paragraph, 'Keadilan juga tercermin dari cara menggunakan fasilitas umum di sekolah. Mencoret-coret meja belajar dengan tip-x, merusak pintu toilet, atau membuang sampah sembarangan berarti merampas hak warga sekolah lainnya untuk menikmati fasilitas tersebut dengan nyaman dan bersih. Pelajar yang beradab sadar bahwa merawat barang milik bersama adalah bentuk penghormatan terhadap hak orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Etika Berinteraksi dengan Seluruh Warga Lingkungan'),
      MateriBlock(MateriBlockType.paragraph, 'Banyak orang yang salah kaprah mengira bahwa sikap sopan santun hanya wajib ditunjukkan kepada kepala sekolah, guru, atau orang tua. Padahal, sila kedua menuntut manusia untuk beradab kepada siapa saja tanpa memandang status pekerjaannya. Menghormati petugas kebersihan, penjaga kantin, dan petugas keamanan sekolah sama pentingnya dengan menghormati guru. Mengucapkan terima kasih setelah menerima kembalian di kantin, menyapa satpam saat memasuki gerbang sekolah, atau membuang sampah pada tempatnya untuk meringankan beban petugas kebersihan adalah contoh nyata perbuatan manusia yang beradab. Perlakuan yang setara inilah yang membedakan remaja yang memiliki integritas moral dengan mereka yang hanya bersikap sopan demi mendapatkan nilai bagus.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga Kemanusiaan di Ruang Digital (Media Sosial)'),
      MateriBlock(MateriBlockType.paragraph, 'Bagi Generasi Z, ruang interaksi utama tidak lagi hanya di lapangan sekolah atau kantin, melainkan bergeser ke media sosial seperti Instagram, TikTok, WhatsApp, dan platform game online. Di ruang digital yang seolah tanpa batas ini, nilai adab sering kali luntur karena pengguna merasa berlindung di balik layar dan nama samaran (anonimitas).'),
      MateriBlock(MateriBlockType.bullet, 'Menyaring Informasi (Saring Sebelum Sharing): Menahan diri untuk tidak menyebarkan berita bohong (hoaks), gosip, atau aib seseorang di media sosial. Menyebarkan rahasia atau video memalukan milik orang lain secara publik sama dengan "membunuh" karakter dan merampas martabat kehormatannya.'),
      MateriBlock(MateriBlockType.bullet, 'Komentar yang Beretika: Menghindari ujaran kebencian (hate speech) saat melihat konten yang tidak disukai. Menggunakan kata-kata kasar, makian, atau sumpah serapah di kolom komentar internet akan meninggalkan jejak digital yang selamanya mencerminkan rendahnya kualitas adab pelakunya.'),
      MateriBlock(MateriBlockType.bullet, 'Merespons Perbedaan Secara Dewasa: Saat terjadi perdebatan di grup obrolan kelas mengenai suatu hal, perbedaan pendapat adalah dinamika yang wajar. Merespons perbedaan tersebut dengan argumen logis tanpa menyerang fisik atau personal lawan bicara menunjukkan kedewasaan berpikir yang sesuai dengan nilai Pancasila.'),
      MateriBlock(MateriBlockType.bullet, 'Menumbuhkan Empati dan Solidaritas Sebaya'),
      MateriBlock(MateriBlockType.paragraph, 'Puncak tertinggi dari kemanusiaan adalah empati, kemampuan untuk merasakan apa yang dirasakan oleh orang lain. Di lingkungan sekolah, empati ini ditunjukkan melalui inisiatif untuk menolong tanpa pamrih. Ketika ada teman yang tertinggal pelajaran karena sakit yang cukup lama, pelajar yang beradab akan berinisiatif meminjamkan buku catatan atau membantunya memahami materi yang terlewat. Kepedulian sosial juga terlihat ketika seluruh siswa aktif ikut serta dalam penggalangan dana saat ada warga sekolah atau masyarakat sekitar yang tertimpa musibah bencana alam. Solidaritas ini membuktikan bahwa rantai kemanusiaan benar-benar saling menguatkan.'),
      MateriBlock(MateriBlockType.paragraph, 'Selain itu, kesetaraan dalam bergaul, terutama terhadap siswa yang memiliki kebutuhan khusus (penyandang disabilitas), sangatlah penting. Perlakuan yang dibutuhkan oleh teman-teman disabilitas bukanlah rasa kasihan yang berlebihan hingga membuat mereka merasa lemah, melainkan dukungan dan perlakuan wajar agar mereka merasa setara, diterima, dan mampu berkarya seperti remaja lainnya. Inilah esensi sejati dari Kemanusiaan yang Adil dan Beradab, memanusiakan manusia dalam segala aspek kehidupannya.'),
      MateriBlock(MateriBlockType.heading, 'Penerapan Sila Ke Tiga Persatuan Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Sila ketiga Pancasila, "Persatuan Indonesia," yang dilambangkan dengan Pohon Beringin, adalah fondasi kokoh yang menjaga keutuhan bangsa di tengah segala perbedaan. Pohon beringin memiliki akar tunjang yang kuat menghunjam ke dalam tanah sebagai simbol kukuhnya persatuan, serta akar gantung yang rimbun mewakili ribuan suku, agama, dan budaya yang bernaung di bawah satu atap Negara Kesatuan Republik Indonesia (NKRI). Bagi pelajar Sekolah Menengah Pertama (SMP), nilai persatuan ini merupakan pedoman kritis untuk membangun solidaritas, menghindari perpecahan, dan menumbuhkan rasa cinta tanah air di tengah derasnya arus globalisasi.'),
      MateriBlock(MateriBlockType.paragraph, 'Menerapkan Sila Ketiga bukan berarti semua orang harus menjadi sama persis atau membuang identitas daerah asalnya. Persatuan justru bermakna merayakan perbedaan tersebut dan menjadikannya sebagai sebuah kekuatan kolektif, sesuai dengan semboyan Bhinneka Tunggal Ika. Berikut adalah penjabaran penerapan Sila Ketiga secara nyata dalam kehidupan sehari-hari para pelajar.'),
      MateriBlock(MateriBlockType.numberedItem, '1. Menghancurkan Tembok Eksklusivitas dan "Geng"'),
      MateriBlock(MateriBlockType.paragraph, 'Di masa transisi remaja, kebutuhan untuk merasa diterima oleh lingkungan pertemanan sangatlah besar. Sayangnya, kondisi ini sering memunculkan "geng" atau kelompok eksklusif yang membatasi pergaulan dan membeda-bedakan status. Penerapan Sila Ketiga secara langsung menentang budaya eksklusivitas yang berpotensi memicu konflik ini.'),
      MateriBlock(MateriBlockType.bullet, 'Berbaur Tanpa Pilih-Pilih: Pelajar yang memiliki jiwa persatuan akan bersedia duduk, belajar, dan berinteraksi dengan siapa saja. Tidak ada sekat pembatas antara siswa yang menonjol secara akademik dengan yang berbakat di bidang olahraga, atau antara siswa dari keluarga berada dengan siswa dari keluarga sederhana.'),
      MateriBlock(MateriBlockType.bullet, 'Menghapus Sentimen Daerah: Saat bersekolah di lingkungan yang majemuk, perbedaan logat bicara, warna kulit, atau tradisi adalah hal yang lumrah. Menjadikan logat daerah teman sebagai bahan ejekan adalah tindakan yang mencederai persatuan. Sebaliknya, perbedaan ini harus dipandang sebagai jendela untuk saling mengenal kekayaan budaya nusantara.'),
      MateriBlock(MateriBlockType.bullet, 'Menolak Fanatisme Almamater yang Merusak: Rasa bangga terhadap sekolah asal adalah hal yang positif, namun fanatisme buta yang berujung pada tawuran antarpelajar adalah pengkhianatan terhadap persatuan bangsa. Seluruh pelajar, dari sekolah mana pun, adalah satu generasi penerus yang seharusnya saling bersinergi, bukan saling menghancurkan di jalanan.'),
      MateriBlock(MateriBlockType.numberedItem, '2. Mengutamakan Kepentingan Bersama (Gotong Royong)'),
      MateriBlock(MateriBlockType.paragraph, 'Persatuan paling mudah dinilai saat sebuah tujuan harus dicapai bersama-sama. Lingkungan sekolah menyediakan banyak ruang untuk melatih kerelaan menekan ego pribadi demi kepentingan kelompok.'),
      MateriBlock(MateriBlockType.bullet, 'Kekompakan dalam Tugas Harian: Melaksanakan jadwal piket kelas tanpa membebankannya hanya pada satu orang adalah wujud persatuan di ruang lingkup terkecil. Setiap siswa mengambil peran spesifik, menyapu, merapikan meja, hingga membuang sampah, demi kenyamanan bersama.'),
      MateriBlock(MateriBlockType.bullet, 'Solidaritas dalam Class Meeting: Saat sekolah mengadakan lomba antarkelas, momen ini menjadi ajang pembuktian persatuan. Kemenangan bukanlah satu-satunya tujuan utama, melainkan bagaimana seluruh anggota kelas bersatu menyusun strategi, saling memberi semangat, dan menjunjung tinggi sportivitas tanpa merendahkan kelas lawan.'),
      MateriBlock(MateriBlockType.bullet, 'Pengorbanan Waktu dan Tenaga: Siswa yang mengorbankan waktu bermainnya demi ikut kerja bakti menghias kelas menjelang 17 Agustus, atau pengurus OSIS yang rela pulang sore untuk menyiapkan acara sekolah, sedang mempraktikkan langsung nilai rela berkorban demi kepentingan bersama.'),
      MateriBlock(MateriBlockType.numberedItem, '3. Menumbuhkan Cinta Tanah Air dan Karya Lokal'),
      MateriBlock(MateriBlockType.paragraph, 'Rasa nasionalisme di era modern tidak selalu menuntut pengorbanan fisik di medan tempur. Bagi generasi muda, patriotisme diwujudkan melalui gaya hidup dan kebanggaan terhadap karya anak bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Bangga Menggunakan Produk Dalam Negeri: Saat ini, banyak merek lokal—mulai dari sepatu, tas, jaket, hingga perlengkapan sekolah—yang kualitasnya mampu bersaing dengan merek internasional. Memilih dan bangga menggunakan produk buatan Indonesia merupakan tindakan nyata memajukan perekonomian bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Menyeimbangkan Arus Globalisasi: Menyukai musik pop Korea (K-Pop), animasi Jepang, atau budaya pop Barat adalah bagian dari pergaulan global yang wajar. Namun, kecintaan terhadap budaya luar tidak boleh mematikan rasa hormat terhadap identitas sendiri. Generasi yang bersatu tetap antusias mempelajari tarian daerah, memakai batik dengan bangga, dan menjaga bahasa Indonesia yang baik dan benar.'),
      MateriBlock(MateriBlockType.bullet, 'Mengukir Prestasi: Mengikuti kompetisi sains, olimpiade matematika, atau turnamen olahraga hingga ke tingkat nasional adalah bentuk kontribusi aktif mengharumkan nama sekolah dan bangsa.'),
      MateriBlock(MateriBlockType.numberedItem, '4. Menjaga Persatuan di Ruang Digital (Cyber Nationalism)'),
      MateriBlock(MateriBlockType.paragraph, 'Interaksi remaja saat ini sangat kental dengan dunia maya dan media sosial. Sayangnya, internet sering kali menjadi arena yang paling mudah digunakan untuk memecah belah bangsa melalui ujaran kebencian.'),
      MateriBlock(MateriBlockType.bullet, 'Memutus Rantai Hoaks: Berita bohong yang membawa narasi provokatif sangat berbahaya bagi persatuan masyarakat. Netizen yang cerdas akan selalu memverifikasi kebenaran sebuah informasi sebelum membagikannya (forward) ke grup obrolan. Menolak menyebarkan hoaks berarti menyelamatkan lingkungan dari adu domba.'),
      MateriBlock(MateriBlockType.bullet, 'Mencegah Perang Sentimen di Kolom Komentar: Saat melihat perdebatan di media sosial yang membawa-bawa nama suku atau daerah, pelajar yang berkarakter tidak akan ikut memanaskan suasana. Mereka memilih untuk menahan jari dari komentar beracun (toxic) yang bisa memicu permusuhan.'),
      MateriBlock(MateriBlockType.bullet, 'Menjadi Representasi Positif Bangsa: Saat berinteraksi dengan orang dari berbagai negara melalui game online atau forum internasional, sikap seorang pemain akan menjadi cerminan negaranya. Berperilaku suportif dan menolak menggunakan makian di server global adalah wujud nyata membela kehormatan dan martabat Indonesia di mata dunia.'),
      MateriBlock(MateriBlockType.paragraph, 'Menjadikan Sila Ketiga sebagai pedoman hidup memastikan bahwa di balik segala perbedaan hobi, minat, dan latar belakang, ada satu ikatan kuat yang tidak boleh putus: status sebagai warga negara Indonesia. Jika nilai persatuan ini dipupuk kuat sejak masa SMP, generasi penerus tidak akan mudah dipecah belah oleh provokasi, dan negara ini akan terus berdiri tegak menaungi seluruh rakyatnya.'),
      MateriBlock(MateriBlockType.heading, 'Penerapan Sila Keempat Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan'),
      MateriBlock(MateriBlockType.paragraph, 'Sila keempat Pancasila, "Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan" yang dilambangkan dengan Kepala Banteng, merupakan prinsip utama jalannya demokrasi di Indonesia. Banteng dipilih sebagai simbol karena habitat aslinya adalah hewan sosial yang memiliki kebiasaan berkumpul dan menjadi lebih kuat saat berada dalam kawanan. Filosofi ini sangat merepresentasikan budaya bangsa Indonesia yang selalu mengutamakan musyawarah dan diskusi komunal dalam menyelesaikan masalah atau mengambil keputusan penting.'),
      MateriBlock(MateriBlockType.paragraph, 'Bagi pelajar Sekolah Menengah Pertama (SMP), usia ini adalah fase penting untuk belajar berorganisasi, menyampaikan pendapat, dan menghargai pola pikir orang lain. Menerapkan Sila Keempat berarti melatih diri untuk tidak egois dan menyingkirkan sikap "mau menang sendiri". Penerapan Sila Keempat berpusat pada tiga kata kunci utama: Musyawarah, Mufakat, dan Kebijaksanaan. Musyawarah adalah proses membicarakan suatu masalah secara bersama-sama untuk mencari jalan keluar. Mufakat adalah hasil akhir atau kesepakatan bulat yang dicapai dari musyawarah tersebut. Sedangkan kebijaksanaan adalah sikap menggunakan akal sehat, hati nurani, dan pengendalian emosi selama proses musyawarah berlangsung, sehingga keputusan yang diambil tidak merugikan pihak mana pun. Di lingkungan sekolah, prinsip ini mengajarkan bahwa suara setiap siswa sangatlah berharga. Tidak ada satu pun individu, meskipun ia anak yang paling pintar di kelas atau berasal dari keluarga terpandang, yang berhak mendikte atau memaksakan kehendaknya kepada teman-teman yang lain.'),
      MateriBlock(MateriBlockType.paragraph, 'Berikut adalah uraian mendalam mengenai bagaimana nilai-nilai kebijaksanaan, musyawarah, dan demokrasi diterapkan secara nyata dalam kehidupan sehari-hari para pelajar.'),
      MateriBlock(MateriBlockType.bullet, 'Praktik Demokrasi di Ruang Kelas'),
      MateriBlock(MateriBlockType.paragraph, 'Ruang kelas adalah laboratorium demokrasi pertama yang paling efektif bagi seorang remaja. Di sinilah nilai-nilai Sila Keempat diuji setiap harinya melalui dinamika pengambilan keputusan bersama.'),
      MateriBlock(MateriBlockType.bullet, 'Pemilihan Pengurus Kelas: Saat tahun ajaran baru dimulai, proses pemilihan ketua kelas, wakil, sekretaris, dan bendahara harus dilakukan secara terbuka. Proses ini bisa melalui diskusi mufakat atau pemungutan suara terbanyak (voting). Pelajar yang memiliki jiwa Pancasila akan memilih pemimpin berdasarkan kecakapan dan rasa tanggung jawabnya, bukan semata-mata karena ia populer atau teman satu geng.'),
      MateriBlock(MateriBlockType.bullet, 'Menyelesaikan Konflik Melalui Diskusi: Ketika terjadi perselisihan, misalnya ketidaksepakatan tentang tema dekorasi kelas untuk lomba, cara menyelesaikannya bukanlah dengan adu mulut atau perkelahian. Siswa yang bijaksana akan duduk bersama, membeberkan argumen masing-masing secara logis, dan mencari jalan tengah yang bisa memuaskan semua pihak.'),
      MateriBlock(MateriBlockType.bullet, 'Distribusi Tugas Kelompok yang Proporsional: Saat mengerjakan tugas dari guru, penentuan siapa yang mencari materi, siapa yang membuat presentasi, dan siapa yang bertugas mempresentasikan harus dirundingkan bersama. Pengambilan keputusan sepihak oleh ketua kelompok tanpa mendengarkan kesanggupan anggotanya adalah bentuk pelanggaran nilai musyawarah.'),
      MateriBlock(MateriBlockType.bullet, 'Keberanian Menyampaikan Pendapat dan Sikap Kritis'),
      MateriBlock(MateriBlockType.paragraph, 'Menerapkan Sila Keempat tidak berarti harus selalu diam dan hanya mengangguk setuju pada keputusan mayoritas. Justru, demokrasi menuntut partisipasi aktif dari setiap individu.'),
      MateriBlock(MateriBlockType.bullet, 'Berani Speak Up (Bicara): Pelajar didorong untuk berani mengangkat tangan dan menyampaikan ide atau gagasannya, baik saat rapat Organisasi Siswa Intra Sekolah (OSIS), kegiatan Pramuka, maupun di tengah pelajaran. Keberanian menyuarakan opini adalah fondasi kerakyatan yang sehat.'),
      MateriBlock(MateriBlockType.bullet, 'Menyampaikan Kritik dengan Etika: Saat melihat kebijakan sekolah atau keputusan pengurus kelas yang dianggap kurang tepat, siswa berhak memberikan kritik. Namun, kritik tersebut harus disampaikan dengan bahasa yang santun, logis, dan idealnya disertai dengan solusi alternatif. Mengkritik dengan nada mencemooh atau menghina justru menghilangkan esensi "kebijaksanaan" dalam sila ini.'),
      MateriBlock(MateriBlockType.bullet, 'Menerima Kekalahan dan Keputusan Bersama'),
      MateriBlock(MateriBlockType.paragraph, 'Ini adalah ujian terberat dalam penerapan Sila Keempat. Sangat mudah untuk berdemokrasi saat pendapat kita yang terpilih, namun dibutuhkan kebesaran hati yang luar biasa untuk tetap mendukung keputusan ketika pendapat kita ditolak.'),
      MateriBlock(MateriBlockType.bullet, 'Lapang Dada Menerima Hasil Mufakat: Jika dalam sebuah diskusi kelas diputuskan suatu hal yang berbeda dari usulan pribadi, sikap yang benar adalah menerima keputusan tersebut dengan ikhlas. Merasa ngambek, memisahkan diri, atau bersikap sabotase agar rencana kelas gagal karena idenya tidak dipakai adalah sikap yang sangat kekanak-kanakan dan anti-demokrasi.'),
      MateriBlock(MateriBlockType.bullet, 'Tanggung Jawab Menjalankan Keputusan: Setelah sebuah keputusan diketuk palu, seluruh anggota kelas wajib melaksanakannya dengan penuh tanggung jawab, terlepas dari apakah mereka sebelumnya setuju atau tidak. Inilah esensi dari keterwakilan dan kebijaksanaan komunal.'),
      MateriBlock(MateriBlockType.bullet, 'Demokrasi dan Etika di Ruang Digital'),
      MateriBlock(MateriBlockType.paragraph, 'Di era modern, forum musyawarah tidak lagi terbatas pada meja rapat fisik. Grup WhatsApp, Line, Discord, hingga kolom komentar media sosial telah menjelma menjadi ruang diskusi virtual yang mempertemukan berbagai gagasan.'),
      MateriBlock(MateriBlockType.bullet, 'Menghargai Opini di Grup Obrolan: Saat berdiskusi di dalam grup aplikasi pesan singkat, berikan kesempatan bagi orang lain untuk mengetik dan menyampaikan argumennya secara utuh. Memotong pembicaraan orang lain secara virtual (misalnya dengan membanjiri grup dengan spam stiker agar pesan orang lain tertenggelam) adalah tindakan yang tidak menghargai hak berpendapat.'),
      MateriBlock(MateriBlockType.bullet, 'Menghindari Cancel Culture yang Destruktif: Terkadang, ada teman yang membuat opiniSila keempat Pancasila menempatkan kedaulatan di tangan rakyat dengan mengedepankan asas musyawarah untuk mencapai mufakat. Nilai ini mengajarkan kita untuk mengutamakan kepentingan bersama, menghargai perbedaan pandangan, dan tidak memaksakan kehendak pribadi kepada orang lain.'),
      MateriBlock(MateriBlockType.heading, 'Penerapan Sila Kelima Keadilan Sosial bagi Seluruh Rakyat Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Sila kelima Pancasila, "Keadilan Sosial bagi Seluruh Rakyat Indonesia," yang dilambangkan dengan Padi dan Kapas, merepresentasikan tujuan utama bernegara yaitu kemakmuran yang merata bagi seluruh rakyat. Padi melambangkan ketersediaan pangan (makanan), sedangkan kapas melambangkan sandang (pakaian), yang bermakna bahwa keadilan tidak hanya sebatas aturan hukum, tetapi juga pemenuhan kebutuhan hidup yang layak. Bagi pelajar usia Sekolah Menengah Pertama (SMP), nilai ini adalah landasan untuk membangun kedisiplinan, mempraktikkan gaya hidup sederhana, dan menjunjung tinggi sikap saling menghargai.'),
      MateriBlock(MateriBlockType.paragraph, 'Penerapan sila ini berpusat pada satu prinsip fundamental: keseimbangan antara hak dan kewajiban. Seseorang tidak bisa terus-menerus menuntut haknya tanpa bersedia menunaikan kewajibannya terlebih dahulu. Keadilan sosial juga berarti mengakui bahwa setiap individu berhak mendapatkan perlakuan dan kesempatan yang sama, serta wajib memberikan kontribusi positif bagi lingkungan sekitarnya.'),
      MateriBlock(MateriBlockType.paragraph, 'Berikut adalah uraian mendalam mengenai bagaimana nilai-nilai keadilan sosial bagi seluruh rakyat Indonesia diterapkan secara nyata dalam kehidupan sehari-hari para pelajar.'),
      MateriBlock(MateriBlockType.bullet, 'Membangun Keseimbangan antara Hak dan Kewajiban'),
      MateriBlock(MateriBlockType.paragraph, 'Keadilan Sosial bagi Seluruh Rakyat Indonesia menuntut kesadaran setiap warga negara untuk membangun keseimbangan antara hak dan kewajiban dalam kehidupan bermasyarakat. Hal ini berarti bahwa sebelum menuntut hak pribadi atau kelompok, seseorang wajib mengutamakan pemenuhan tanggung jawab dan kewajibannya terhadap sesama serta lingkungan sosial. Dengan menyeimbangkan kedua hal tersebut, kesenjangan sosial dapat dikurangi, tercipta keadilan yang merata, serta terwujud kehidupan bersama yang harmonis, adil, dan berkeadaban di bawah naungan nilai-nilai luhur Pancasila.'),
      MateriBlock(MateriBlockType.bullet, 'Mengutamakan Kewajiban Sebelum Hak: Setiap pelajar berhak mendapatkan fasilitas belajar yang nyaman dan penilaian yang objektif dari guru. Namun, hak tersebut wajib diimbangi dengan tindakan nyata mengerjakan tugas tepat waktu, mematuhi tata tertib, dan menjaga kebersihan fasilitas sekolah. Menuntut nilai sempurna tanpa mau belajar adalah bentuk ketidakadilan terhadap diri sendiri dan guru.'),
      MateriBlock(MateriBlockType.bullet, 'Menghindari Sikap Pilih Kasih: Dalam pergaulan, bersikap adil berarti tidak membeda-bedakan teman saat memberikan bantuan atau membagi kelompok belajar. Memilih anggota kelompok hanya berdasarkan popularitas tanpa melihat kemauan bekerja keras akan menciptakan ketimpangan dan rasa ketidakadilan di antara anggota.'),
      MateriBlock(MateriBlockType.bullet, 'Menghargai Karya dan Jerih Payah Orang Lain: Memberikan apresiasi saat teman selesai presentasi atau berhasil meraih juara adalah wujud keadilan sosial. Sebaliknya, menjiplak tugas teman secara diam-diam (plagiarisme) atau merusak hasil karya seni milik orang lain merupakan tindakan perampasan hak.'),
      MateriBlock(MateriBlockType.bullet, 'Membangun Gaya Hidup Sederhana dan Pekerja Keras'),
      MateriBlock(MateriBlockType.paragraph, 'Penerapan sila kelima Pancasila dapat diwujudkan melalui pembentukan gaya hidup sederhana dan etos kerja keras guna menghindari sifat pemborosan serta menghargai setiap keringat perjuangan dalam mencapai kesejahteraan bersama.'),
      MateriBlock(MateriBlockType.bullet, 'Menolak Budaya Pamer (Flexing): Di era media sosial, godaan untuk memamerkan barang-barang bermerek atau gawai (gadget) terbaru sangatlah besar. Sila kelima menentang keras gaya hidup boros dan berlebih-lebihan. Pelajar yang berkarakter Pancasila menyadari bahwa memamerkan kemewahan secara berlebihan dapat melukai perasaan teman-teman yang kondisi ekonomi keluarganya kurang beruntung.'),
      MateriBlock(MateriBlockType.bullet, 'Membiasakan Diri Menabung: Menyisihkan sebagian uang saku untuk ditabung jauh lebih bijak daripada menghabiskannya untuk membeli hal-hal yang sekadar menuruti gengsi. Sikap hemat ini melatih kemandirian serta menghargai nilai uang yang dicari dengan kerja keras oleh orang tua.'),
      MateriBlock(MateriBlockType.bullet, 'Menunjukkan Etos Kerja Keras: Keadilan sosial mustahil diraih melalui kemalasan. Belajar dengan tekun, pantang menyerah saat menghadapi materi ujian yang sulit, dan aktif berkontribusi dalam kegiatan sekolah adalah bentuk kerja keras yang diamanatkan oleh sila kelima.'),
      MateriBlock(MateriBlockType.bullet, 'Keadilan di Ranah Digital'),
      MateriBlock(MateriBlockType.paragraph, 'Penerapan sila kelima Pancasila di era digital dapat diwujudkan dengan memastikan pemerataan akses teknologi serta menciptakan ruang digital yang aman, santun, dan bebas dari disinformasi bagi seluruh masyarakat tanpa diskriminasi.'),
      MateriBlock(MateriBlockType.bullet, 'Menghargai Hak Cipta Intelektual: Mengunduh film, lagu, atau aplikasi bajakan secara ilegal adalah tindakan merampas hak ekonomi para penciptanya. Menikmati hiburan digital melalui platform resmi merupakan bentuk nyata keadilan sosial bagi para kreator di dunia maya.'),
      MateriBlock(MateriBlockType.bullet, 'Berbagi Fasilitas Publik: Saat menggunakan komputer perpustakaan sekolah atau Wi-Fi publik, pelajar yang adil tidak akan memonopoli penggunaan internet untuk mengunduh fail pribadi yang sangat besar. Kesadaran bahwa orang lain juga memiliki hak dan kebutuhan yang sama atas fasilitas tersebut adalah wujud nyata kepedulian sosial.'),
      MateriBlock(MateriBlockType.paragraph, 'Menanamkan prinsip keadilan sosial sejak masa remaja akan membentuk generasi yang tangguh dan tidak egois. Ketika setiap individu mampu menakar porsi hak dan kewajibannya dengan tepat, serta rela bekerja keras tanpa berniat merugikan orang lain, maka harmoni, kesetaraan, dan kesejahteraan bersama di lingkungan sekolah akan tercipta dengan sendirinya.'),
    ],
  ),
  MateriSection(
    id: 'kelas7-materi-3',
    number: 3,
    title: 'Norma Dan Keadilan',
    summary: 'Manusia diciptakan sebagai makhluk sosial (zoon politikon), yang artinya manusia tidak dapat hidup sendiri dan selalu membutuhkan orang lain untuk memenuhi kebutuhan hidupnya. Dalam proses berinteraksi sehari-hari, baik di lingkungan rumah, sekolah, maupun Masyarakat, setiap orang memiliki keinginan, kepentingan, dan karakter yang berbeda-beda. Jika setiap individu bertindak sesuka hati tanpa ada aturan yang membatasi, maka perselisihan, kekacauan, dan benturan kepentingan akan sangat mudah terjadi. Oleh karena itu, masyarakat membutuhkan pedoman bertingkah laku yang disebut dengan norma.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Pengertian Norma'),
      MateriBlock(MateriBlockType.heading, 'Secara etimologi atau asal-usul kata, kata “norma” berasal dari bahasa Latin norma, yang berarti siku-siku, sebuah alat tukang kayu yang digunakan untuk mengukur apakah sebuah sudut sudah lurus dan presisi. Dalam bahasa Arab, norma dikenal dengan istilah kaidah, yang berarti aturan atau pedoman. Secara umum, norma adalah kaidah, aturan, atau pedoman hidup yang disepakati oleh masyarakat untuk mengatur tingkah laku manusia dalam berinteraksi satu sama lain.'),
      MateriBlock(MateriBlockType.paragraph, 'Memudahkan pemahaman, bayangkan norma seperti “aturan main” dalam sebuah pertandingan olahraga. Dalam permainan sepak bola, terdapat aturan yang melarang pemain memegang bola dengan tangan (kecuali kiper) atau menakel lawan secara berbahaya. Tanpa adanya aturan main tersebut, pertandingan tidak akan berjalan adil, aman, maupun menyenangkan. Begitu pula dalam kehidupan nyata. Norma hadir untuk memastikan bahwa hak setiap orang terlindungi dan kewajiban setiap individu dijalankan dengan penuh tanggung jawab.'),
      MateriBlock(MateriBlockType.bullet, 'Fungsi Utama Norma dalam Masyarakat'),
      MateriBlock(MateriBlockType.paragraph, 'Pemahaman yang mendalam mengenai fungsi utama norma ini sangat penting agar setiap individu mampu menjalankan perannya dengan penuh kesadaran dan tanggung jawab sosial. Fungsi norma diantaranya sebagai berikut:'),
      MateriBlock(MateriBlockType.bullet, 'Menciptakan Ketertiban dan Keamanan: Mengatur lalu lintas hubungan antarmanusia agar tidak saling merugikan.'),
      MateriBlock(MateriBlockType.bullet, 'Petunjuk Arah Berperilaku: Memberikan batasan yang jelas mengenai tindakan mana yang boleh dilakukan dan mana yang harus dihindari.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga Keharmonisan Sosial: Mencegah terjadinya konflik sosial akibat perbedaan kepentingan.'),
      MateriBlock(MateriBlockType.bullet, 'Wadah Keadilan: Memastikan bahwa setiap warga masyarakat mendapatkan perlakuan yang sama dan seimbang.'),
      MateriBlock(MateriBlockType.bullet, 'Jenis Norma dalam Masyarakat'),
      MateriBlock(MateriBlockType.paragraph, 'Berdasarkan sumber, sifat, dan sanksinya, norma yang berlaku dalam kehidupan masyarakat dibagi menjadi empat jenis utama, yaitu norma agama, norma kesusilaan, norma kesopanan, dan norma hukum.'),
      MateriBlock(MateriBlockType.heading, 'Norma Agama'),
      MateriBlock(MateriBlockType.paragraph, 'Norma agama adalah sekumpulan kaidah atau petunjuk hidup yang bersumber langsung dari wahyu Tuhan Yang Maha Esa, yang disampaikan melalui para nabi dan rasul, serta dihimpun dalam kitab-kitab suci.'),
      MateriBlock(MateriBlockType.bullet, 'Sifat: Sifat norma agama adalah dogmatis dan mutlak. Artinya, aturan di dalamnya tidak boleh diubah, dikurangi, atau ditawar-tawar oleh manusia. Norma ini berlaku bagi seluruh pemeluk agama yang bersangkutan di mana pun mereka berada.'),
      MateriBlock(MateriBlockType.bullet, 'Sanksi: Sanksi atas pelanggaran norma agama bersifat spiritual dan tidak langsung dirasakan di dunia. Pelanggar norma ini akan mendapatkan dosa dan balasan di akhirat kelak sesuai dengan ajaran agamanya masing-masing.'),
      MateriBlock(MateriBlockType.heading, 'Contoh Penerapan:'),
      MateriBlock(MateriBlockType.bullet, 'Melaksanakan ibadah tepat waktu sesuai ajaran agama yang dianut (seperti salat, kebaktian, atau puja bakti).'),
      MateriBlock(MateriBlockType.bullet, 'Membaca dan mempelajari kitab suci.'),
      MateriBlock(MateriBlockType.bullet, 'Menjauhi larangan agama, seperti mencuri, berbohong, memfitnah, dan menyakiti sesama makhluk hidup.'),
      MateriBlock(MateriBlockType.bullet, 'Menghormati dan berbakti kepada orang tua.'),
      MateriBlock(MateriBlockType.heading, 'Norma Kesusilaan'),
      MateriBlock(MateriBlockType.paragraph, 'Norma kesusilaan adalah aturan hidup yang bersumber dari hati nurani atau bisikan sanubari manusia. Setiap manusia yang lahir dibekali oleh Tuhan dengan dorongan alamiah untuk mencintai kebaikan dan membenci keburukan. Hati nurani inilah yang menjadi “kompas moral” internal bagi seseorang.'),
      MateriBlock(MateriBlockType.bullet, 'Sifat: Norma kesusilaan bersifat universal. Artinya, nilai-nilai di dalamnya diakui oleh seluruh manusia di dunia tanpa memandang suku, bangsa, agama, maupun kebudayaan. Kejujuran, misalnya, dianggap sebagai hal positif oleh semua masyarakat di bumi.'),
      MateriBlock(MateriBlockType.bullet, 'Sanksi: Sanksi pelanggaran norma kesusilaan berasal dari dalam diri sendiri, berupa perasaan bersalah, penyesalan yang mendalam, rasa malu, gelisah, dan ketidaktenangan batin.'),
      MateriBlock(MateriBlockType.heading, 'Contoh Penerapan:'),
      MateriBlock(MateriBlockType.bullet, 'Menolak untuk mencontek saat ujian atau ulangan di sekolah, meskipun ada kesempatan.'),
      MateriBlock(MateriBlockType.bullet, 'Mengembalikan barang berharga atau uang milik orang lain yang ditemukan di jalan.'),
      MateriBlock(MateriBlockType.bullet, 'Mengaku dengan jujur ketika melakukan kesalahan tanpa melemparkan kesalahan kepada orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Bersikap empati dan menolong teman yang sedang berada dalam kesulitan.'),
      MateriBlock(MateriBlockType.heading, 'Norma Kesopanan'),
      MateriBlock(MateriBlockType.paragraph, 'Norma kesopanan adalah aturan bertingkah laku yang bersumber dari kebiasaan, pergaulan, dan tata krama yang tumbuh serta berkembang dalam suatu kelompok masyarakat tertentu. Norma ini mengatur etika pergaulan sehari-hari agar hubungan sosial terasa menyenangkan dan saling menghargai.'),
      MateriBlock(MateriBlockType.bullet, 'Sifat: Sifat norma kesopanan adalah relatif dan kedaerahan. Artinya, apa yang dianggap sopan di satu tempat atau budaya belum tentu dianggap sopan di tempat lain. Ukuran kesopanan sangat dipengaruhi oleh tradisi setempat dan bisa berubah seiring perkembangan zaman.'),
      MateriBlock(MateriBlockType.bullet, 'Sanksi: Sanksi atas pelanggaran norma kesopanan bersifat sosial. Pelanggar akan mendapat cemoohan, teguran, celaan, dianggap tidak beradat, hingga dikucilkan dari lingkungan pergaulan.'),
      MateriBlock(MateriBlockType.heading, 'Contoh Penerapan:'),
      MateriBlock(MateriBlockType.bullet, 'Mengucapkan salam dan mencium tangan atau membungkukkan badan saat berpapasan dengan orang tua atau guru.'),
      MateriBlock(MateriBlockType.bullet, 'Menggunakan kata-kata yang santun dan menolak menggunakan bahasa kasar saat berbicara dengan orang lain.'),
      MateriBlock(MateriBlockType.bullet, 'Makan dan minum menggunakan tangan kanan serta tidak mengenakan topi di dalam ruang kelas saat pelajaran berlangsung.'),
      MateriBlock(MateriBlockType.bullet, 'Menghormati orang yang lebih tua dan menyayangi orang yang lebih muda.'),
      MateriBlock(MateriBlockType.heading, 'Norma Hukum'),
      MateriBlock(MateriBlockType.paragraph, 'Norma hukum adalah aturan bertingkah laku yang dibuat oleh lembaga-lembaga resmi negara yang berwenang (seperti DPR dan Pemerintah) yang bertujuan untuk mengatur ketertiban hidup bermasyarakat, berbangsa, dan bernegara.'),
      MateriBlock(MateriBlockType.bullet, 'Sifat: Sifat norma hukum adalah mengikat, tegas, dan memaksa (coercive). Mengikat artinya aturan ini berlaku untuk seluruh warga negara tanpa kecuali. Memaksa artinya negara memiliki alat-alat kelengkapan (seperti polisi, jaksa, dan hakim) untuk menindak siapa saja yang melanggarnya.'),
      MateriBlock(MateriBlockType.bullet, 'Sanksi: Sanksi norma hukum bersifat nyata, tegas, dan terukur secara tertulis dalam kitab undang-undang. Bentuk sanksinya dapat berupa hukuman penjara, kurungan, denda berupa uang, hingga pencabutan hak-hak tertentu.'),
      MateriBlock(MateriBlockType.heading, 'Contoh Penerapan:'),
      MateriBlock(MateriBlockType.bullet, 'Mematuhi peraturan lalu lintas, seperti memakai helm standar saat naik sepeda motor dan memiliki Surat Izin Mengemudi (SIM) bagi yang sudah cukup umur.'),
      MateriBlock(MateriBlockType.bullet, 'Dilarang keras melakukan tindakan pidana, seperti mencuri, merusak fasilitas umum, penganiayaan, dan membunuh.'),
      MateriBlock(MateriBlockType.bullet, 'Wajib membayar pajak kepada negara sesuai dengan ketentuan perundang-undangan.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga ketertiban umum dan menolak segala bentuk perbuatan perusakan atau tawuran.'),
      MateriBlock(MateriBlockType.bullet, 'Hubungan Saling Melengkapi Antarjenis Norma'),
      MateriBlock(MateriBlockType.paragraph, 'Keempat jenis norma di atas tidak berdiri sendiri-sendiri secara terpisah, melainkan saling melengkapi dan memperkuat satu sama lain dalam membentuk tatanan masyarakat yang harmonis.'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai contoh, tindakan mencuri:'),
      MateriBlock(MateriBlockType.bullet, 'Secara norma agama, mencuri adalah perbuatan dosa yang dilarang Tuhan.'),
      MateriBlock(MateriBlockType.bullet, 'Secara norma kesusilaan, mencuri membuat hati nurani merasa bersalah dan malu.'),
      MateriBlock(MateriBlockType.bullet, 'Secara norma kesopanan, mencuri adalah perbuatan yang sangat tercela dalam pergaulan.'),
      MateriBlock(MateriBlockType.bullet, 'Secara norma hukum, mencuri akan ditangkap polisi dan diancam hukuman penjara.'),
      MateriBlock(MateriBlockType.paragraph, 'Dengan demikian, ketika keempat norma ini dipatuhi secara seimbang, maka akan tercipta lingkungan yang tidak hanya aman secara hukum, tetapi juga tenang secara batin, santun dalam budaya, dan terarah secara spiritual.'),
      MateriBlock(MateriBlockType.bullet, 'Pentingnya Mematuhi Norma bagi Pelajar SMP'),
      MateriBlock(MateriBlockType.heading, 'Sebagai seorang pelajar yang sedang berada pada fase remaja, kepatuhan terhadap norma bukanlah pembatasan kebebasan, melainkan latihan pembentukan integritas moral dan karakter diri. Pelajar yang terbiasa hidup tertib dan menaati aturan sejak dini akan tumbuh menjadi pribadi yang bertanggung jawab, disukai dalam pergaulan, dan siap menjadi warga negara yang beradab.'),
      MateriBlock(MateriBlockType.paragraph, 'Mulailah dari langkah-langkah kecil di lingkungan sekitar: hormati guru dan orang tua, bersikap jujur saat ulangan, gunakan media sosial dengan santun, serta patuhi tata tertib sekolah. Kepatuhan terhadap norma adalah investasi terbaik untuk masa depan diri sendiri dan bangsa.'),
    ],
  ),
  MateriSection(
    id: 'kelas7-materi-4',
    number: 4,
    title: 'Memahami Keragaman Dalam Bingkai Persatuan',
    summary: 'Indonesia dikenal di mata dunia sebagai negara kepulauan terbesar yang memiliki kekayaan budaya luar biasa. Jika dicermati, Indonesia ibarat sebuah taman bunga indah yang menawan bukan karena hanya ada satu warna bunga, melainkan karena beraneka warna dan jenis bunga tumbuh bersama secara harmonis. Keanekaragaman inilah yang dalam materi Pendidikan Pancasila dan Kewarganegaraan (PPKn) dikenal dengan istilah SARA, yaitu singkatan dari Suku, Agama, Ras, dan Antargolongan. Bagi seorang pelajar Sekolah Menengah Pertama (SMP), memahami konsep keragaman SARA sangat penting agar mampu membedakan mana keunikan budaya yang harus disyukuri dan mana potensi konflik yang harus dihindari. Keragaman bukan alasan untuk memisahkan diri, melainkan identitas utama bangsa yang diikat oleh semangat persatuan.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Mengenal Unsur-Unsur Keragaman SARA'),
      MateriBlock(MateriBlockType.paragraph, 'Keragaman masyarakat Indonesia mencakup empat aspek utama yang membentuk identitas kehidupan sosial:'),
      MateriBlock(MateriBlockType.heading, 'Suku Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Suku bangsa adalah sekelompok manusia yang memiliki kesamaan budaya, bahasa daerah, asal-usul, serta adat istiadat yang diwariskan secara turun-temurun. Indonesia memiliki lebih dari 300 kelompok suku bangsa. Contohnya, suku Jawa di Pulau Jawa, suku Batak di Sumatra Utara, suku Dayak di Kalimantan, suku Bugis di Sulawesi, dan suku Asmat di Papua. Setiap suku memiliki kekayaan tarian tradisional, rumah adat, pakaian adat, serta lagu daerah yang unik dan mempesona.'),
      MateriBlock(MateriBlockType.heading, 'Agama dan Kepercayaan'),
      MateriBlock(MateriBlockType.paragraph, 'Sila pertama Pancasila menjamin kebebasan beragama bagi seluruh rakyat Indonesia. Negara secara resmi mengakui enam agama utama, yaitu Islam, Kristen, Katolik, Hindu, Buddha, dan Khonghucu, serta memberikan ruang bagi keberadaan penghayat kepercayaan. Perbedaan ritual ibadah, kitab suci, dan hari besar keagamaan bukanlah pemisah, melainkan pelajaran tentang indahnya saling menghargai keyakinan orang lain.'),
      MateriBlock(MateriBlockType.heading, 'Ras'),
      MateriBlock(MateriBlockType.paragraph, 'Ras adalah pengelompokan manusia berdasarkan ciri-ciri fisik luar yang diturunkan secara biologis, seperti warna kulit, bentuk rambut, bentuk mata, dan tinggi badan. Di Indonesia, terdapat beberapa kelompok ras dominan:'),
      MateriBlock(MateriBlockType.bullet, 'Ras Malayan-Mongoloid: Memiliki ciri kulit sawo matang, rambut lurus atau berombak, dan mata hitam; tersebar di sebagian besar pulau Sumatra, Jawa, Bali, Nusa Tenggara Barat, Kalimantan, dan Sulawesi.'),
      MateriBlock(MateriBlockType.bullet, 'Ras Melanesoid: Memiliki ciri kulit gelap, rambut keriting, dan bibir agak tebal; sebagian besar mendiami wilayah Papua, Maluku, dan Nusa Tenggara Timur.'),
      MateriBlock(MateriBlockType.bullet, 'Ras Asiatic Mongoloid: Merupakan warga keturunan Tionghoa, Korea, atau Jepang dengan ciri kulit kuning langsat dan mata sipit.'),
      MateriBlock(MateriBlockType.bullet, 'Ras Kaukasoid: Merupakan warga keturunan Timur Tengah, India, atau Eropa yang mendiami berbagai wilayah di Indonesia.'),
      MateriBlock(MateriBlockType.heading, 'Antargolongan'),
      MateriBlock(MateriBlockType.paragraph, 'Antargolongan merujuk pada perbedaan kedudukan sosial, struktur ekonomi, tingkat pendidikan, profesi, serta organisasi dalam masyarakat. Dalam kehidupan sosial, terdapat kelompok petani, nelayan, pedagang, pegawai negeri, hingga pengusaha. Ada pula perbedaan tingkat ekonomi. Keragaman antargolongan mengajarkan bahwa setiap profesi dan peran dalam masyarakat saling membutuhkan untuk menjaga roda kehidupan tetap berputar.'),
      MateriBlock(MateriBlockType.bullet, 'Faktor Penyebab Keragaman Masyarakat Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Keberagaman di Indonesia tidak muncul begitu saja, melainkan dipengaruhi oleh lima faktor utama:'),
      MateriBlock(MateriBlockType.bullet, 'Letak Strategis Wilayah Indonesia: Indonesia berada di antara dua samudra (Hindia dan Pasifik) dan dua benua (Asia dan Australia). Letak ini menjadikan Indonesia sebagai jalur perdagangan internasional yang dilewati berbagai bangsa asing yang membawa budaya, agama, dan ras yang berbeda.'),
      MateriBlock(MateriBlockType.bullet, 'Kondisi Negara Kepulauan: Ribuan pulau yang dipisahkan oleh laut membuat tiap-tiap kelompok masyarakat tumbuh menjadi suku bangsa yang memiliki budaya, bahasa, dan kebiasaan tersendiri karena terisolasi secara geografis di masa lalu.'),
      MateriBlock(MateriBlockType.bullet, 'Perbedaan Kondisi Alam: Masyarakat yang tinggal di daerah pesisir pantai berkembang menjadi masyarakat nelayan dengan karakter terbuka. Sementara masyarakat di daerah pegunungan berkembang menjadi petani dengan kebudayaan yang menyesuaikan dengan suhu dingin dan lahan pertanian.'),
      MateriBlock(MateriBlockType.bullet, 'Keadaan Transportasi dan Komunikasi: Kemudahan atau keterbatasan sarana transportasi dan komunikasi memengaruhi seberapa cepat suatu masyarakat menerima pengaruh budaya luar atau berinteraksi dengan kelompok lain.'),
      MateriBlock(MateriBlockType.bullet, 'Penerimaan Masyarakat Terhadap Perubahan: Ada kelompok masyarakat yang sangat terbuka terhadap budaya baru, namun ada juga masyarakat yang tetap teguh memegang tradisi lokal tanpa mau dipengaruhi oleh budaya luar (seperti suku Baduy).'),
      MateriBlock(MateriBlockType.bullet, 'Bhinneka Tunggal Ika: Bingkai Persatuan Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Di bawah kaki burung Garuda Pancasila, tercengkeram erat sebuah pita putih bertuliskan “Bhinneka Tunggal Ika”. Kalimat ini berasal dari kitab Sutasoma karangan Mpu Tantular pada zaman Kerajaan Majapahit, yang berarti “Berbeda-beda tetapi tetap satu jua”. Semboyan ini berfungsi sebagai bingkai perekat yang menyatukan seluruh elemen SARA. Persatuan tidak berarti menghilangkan identitas suku, agama, atau budaya asli seseorang. Persatuan berarti menaruh rasa bangga dan rasa cinta kepada tanah air Indonesia di atas kepentingan kelompok atau golongan pribadi.'),
      MateriBlock(MateriBlockType.paragraph, 'Keberagaman SARA yang dikelola dengan baik akan menjadi kekayaan nasional yang luar biasa, daya tarik wisata dunia, serta benteng kekuatan bangsa. Namun sebaliknya, jika keberagaman diwarnai oleh keegoisan, maka isu SARA sangat rawan dimanfaatkan oleh pihak tidak bertanggung jawab untuk memicu perselisihan dan konflik horizontal.'),
      MateriBlock(MateriBlockType.bullet, 'Sikap Toleransi dan Penerapan dalam Kehidupan Pelajar'),
      MateriBlock(MateriBlockType.paragraph, 'Untuk menjaga keberagaman agar tetap berada dalam bingkai persatuan, setiap pelajar perlu mempraktikkan sikap toleransi dalam kehidupan sehari-hari:'),
      MateriBlock(MateriBlockType.bullet, 'Toleransi Beragama: Tidak mengganggu teman yang sedang beribadah, tidak memaksakan ajaran agama sendiri kepada pemeluk agama lain, serta menjaga ketenangan saat hari raya agama lain.'),
      MateriBlock(MateriBlockType.bullet, 'Menolak Perundungan Berbasis Rasisme: Tidak mengejek warna kulit, bentuk rambut, atau logat bahasa teman yang berasal dari daerah lain. Menghindari segala bentuk candaan yang merendahkan fisik atau suku tertentu.'),
      MateriBlock(MateriBlockType.bullet, 'Pertemanan Inklusif: Membuka diri untuk berteman dan bekerja sama dengan siapa saja di sekolah tanpa membuat kelompok eksklusif yang hanya mau bergaul dengan sesama suku atau agama.'),
      MateriBlock(MateriBlockType.bullet, 'Bijak di Media Sosial: Tidak ikut menyebarkan ujaran kebencian (hate speech), berita bohong (hoax), atau meme yang memecah belah persatuan suku dan agama di ruang digital.'),
      MateriBlock(MateriBlockType.paragraph, 'Keragaman Suku, Agama, Ras, dan Antargolongan adalah anugerah terbesar dari Tuhan Yang Maha Esa bagi bangsa Indonesia. Keberagaman bukan merupakan penghambat kemajuan, melainkan modal utama untuk membangun bangsa yang besar dan kuat. Dengan memegang teguh semangat Bhinneka Tunggal Ika dan nilai-nilai Pancasila, generasi muda Indonesia akan mampu merawat kedamaian, mempererat persahabatan antar-anak bangsa, dan membawa Indonesia menjadi negara yang disegani oleh dunia.'),
    ],
  ),
  MateriSection(
    id: 'kelas7-materi-5',
    number: 5,
    title: 'Wilayah Negara Kesatuan Republik Indonesia',
    summary: 'Bayangkan negara kita, Indonesia, sebagai sebuah rumah keluarga raksasa yang sangat luas dan kaya. Rumah ini tidak hanya terdiri dari lantai tempat kita berpijak yang berupa ribuan pulau (wilayah darat), tetapi juga dihubungkan oleh halaman air yang sangat luas (wilayah laut), serta memiliki atap pelindung yang tak terbatas di atasnya (wilayah udara). Mempelajari bentangan Wilayah Negara Kesatuan Republik Indonesia (NKRI) dari Sabang sampai Merauke ini sangatlah penting, bukan sekadar untuk menghafal batas-batas di peta, melainkan agar kita semakin mengenal, mencintai, dan pada akhirnya siap menjaga "rumah" kebanggaan kita ini dengan sebaik-baiknya.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Makna Negara dan Unsur-Unsur Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Negara adalah sebuah organisasi kekuasaan yang memiliki wilayah tertentu, didiami oleh rakyat, dan memiliki pemerintahan yang berdaulat untuk mengatur segala urusan demi mencapai tujuan bersama. Bagi siswa SMP, bayangkan negara seperti sebuah sekolah besar. Sekolah memiliki murid (rakyat), gedung dan lapangan (wilayah), kepala sekolah beserta guru (pemerintah), dan diakui oleh dinas pendidikan (pengakuan pihak luar). Tanpa salah satu dari unsur ini, sekolah tersebut tidak bisa beroperasi dengan baik.'),
      MateriBlock(MateriBlockType.paragraph, 'Secara hukum dan ilmu tata negara, sebuah negara baru bisa disebut sebagai "negara" yang sah jika memenuhi empat unsur pembentuk, yaitu tiga unsur konstitutif (mutlak) dan satu unsur deklaratif (tambahan/pengakuan).'),
      MateriBlock(MateriBlockType.heading, 'Unsur Konstitutif (Mutlak Harus Ada) diantaranya:'),
      MateriBlock(MateriBlockType.bullet, 'Rakyat (Penduduk dan Bukan Penduduk): Rakyat adalah semua orang yang berada di wilayah suatu negara dan taat pada peraturan negara tersebut. Rakyat dibedakan menjadi penduduk (mereka yang menetap, baik Warga Negara Indonesia maupun Warga Negara Asing yang punya izin tinggal) dan bukan penduduk (seperti turis asing yang hanya berkunjung sementara). Tanpa rakyat, tidak akan ada yang diatur dan tidak ada yang membela negara.'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah: Wilayah adalah ruang tempat rakyat hidup dan pemerintah menjalankan kekuasaannya. Wilayah ini tidak hanya berupa tanah, tetapi memiliki cakupan yang luas:'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah Darat: Daratan yang dibatasi oleh batas alam (gunung, sungai), batas buatan (pagar, tembok), atau batas astronomis.'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah Laut (Perairan): Lautan yang berada di dalam wilayah daratan maupun yang berbatasan dengan perairan internasional.'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah Udara: Ruang udara yang berada tepat di atas wilayah darat dan laut negara tersebut.'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah Ekstrateritorial: Tempat yang menurut hukum internasional diakui sebagai wilayah suatu negara meskipun letaknya ada di negara lain, contohnya adalah Kantor Kedutaan Besar Republik Indonesia (KBRI) di luar negeri atau kapal berbendera Indonesia di laut lepas.'),
      MateriBlock(MateriBlockType.bullet, 'Pemerintah yang Berdaulat: Pemerintah adalah lembaga yang memiliki kewenangan untuk mengatur kehidupan rakyat dan menjaga wilayah. Berdaulat artinya pemerintah memiliki kekuasaan tertinggi yang dihormati oleh rakyatnya (kedaulatan ke dalam) dan setara dengan negara-lain serta tidak tunduk pada campur tangan negara asing (kedaulatan ke luar).'),
      MateriBlock(MateriBlockType.heading, 'Unsur Deklaratif (Pelengkap) adalah Pengakuan dari Negara Lain: Meskipun sebuah negara sudah punya rakyat, wilayah, dan pemerintah, ia tetap membutuhkan pengakuan dari negara lain agar bisa bekerja sama secara internasional (seperti berdagang atau bertukar duta besar). Pengakuan ini terbagi dua:'),
      MateriBlock(MateriBlockType.bullet, 'De facto: Pengakuan berdasarkan fakta atau kenyataan bahwa negara tersebut memang sudah berdiri.'),
      MateriBlock(MateriBlockType.bullet, 'De jure: Pengakuan secara hukum internasional yang resmi, sehingga negara tersebut sah menjadi bagian dari pergaulan global.'),
      MateriBlock(MateriBlockType.bullet, 'Wilayah Negara Kesatuan Republik Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Indonesia memiliki karakteristik wilayah yang sangat unik dan berbeda dari kebanyakan negara di dunia. Pasal 25A Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 (UUD 1945) secara tegas menyebutkan bahwa "Negara Kesatuan Republik Indonesia adalah sebuah negara kepulauan yang berciri Nusantara dengan wilayah dan batas-batas serta hak-haknya ditetapkan dengan undang-undang." Makna "Berciri Nusantara" berarti lautan di Indonesia bukanlah pemisah antar pulau, melainkan pemersatu yang merangkai ribuan pulau menjadi satu kesatuan yang utuh.'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai negara kepulauan terbesar di dunia dengan lebih dari 17.000 pulau, batas wilayah Indonesia diatur secara ketat, terutama melalui Deklarasi Djuanda 13 Desember 1957 dan diakui oleh PBB melalui hukum laut internasional (UNCLOS 1982).'),
      MateriBlock(MateriBlockType.heading, 'Batas Darat: Wilayah darat Indonesia berbatasan langsung dengan tiga negara:'),
      MateriBlock(MateriBlockType.bullet, 'Bagian utara: Berbatasan dengan Malaysia (di Pulau Kalimantan/Borneo).'),
      MateriBlock(MateriBlockType.bullet, 'Bagian timur: Berbatasan dengan Papua Nugini (di Pulau Papua).'),
      MateriBlock(MateriBlockType.bullet, 'Bagian selatan: Berbatasan dengan Timor Leste (di Pulau Timor).'),
      MateriBlock(MateriBlockType.heading, 'Batas Laut: Pembagian wilayah perairan Indonesia sangat penting untuk melindungi kekayaan alam seperti ikan dan minyak bumi. Pembagiannya meliputi:'),
      MateriBlock(MateriBlockType.bullet, 'Laut Teritorial: Jalur laut selebar 12 mil laut yang diukur dari garis pangkal kepulauan Indonesia. Di zona ini, Indonesia memiliki kedaulatan penuh, termasuk atas ruang udara di atasnya dan dasar laut di bawahnya.'),
      MateriBlock(MateriBlockType.bullet, 'Zona Ekonomi Eksklusif (ZEE): Jalur laut selebar 200 mil laut ke arah laut terbuka. Di sini, kapal asing boleh lewat, tetapi hanya Indonesia yang berhak memanfaatkan sumber daya alamnya (seperti menangkap ikan atau menambang minyak).'),
      MateriBlock(MateriBlockType.bullet, 'Landas Kontinen: Dasar laut dan tanah di bawahnya yang merupakan kelanjutan alamiah dari wilayah daratan, hingga kedalaman tertentu. Indonesia memiliki hak eksklusif untuk mengeksplorasi bahan tambang di dasar laut ini.'),
      MateriBlock(MateriBlockType.paragraph, 'Posisi Silang Strategis: Wilayah Indonesia terletak di antara dua benua (Asia dan Australia) serta dua samudra (Hindia dan Pasifik). Posisi ini membuat perairan Indonesia menjadi jalur perdagangan internasional yang sangat ramai. Selain itu, Indonesia berada di jalur Ring of Fire (Cincin Api Pasifik) yang membuatnya memiliki banyak gunung berapi dan tanah yang subur, meski juga rawan gempa.'),
      MateriBlock(MateriBlockType.bullet, 'Indonesia sebagai Negara Kesatuan'),
      MateriBlock(MateriBlockType.paragraph, 'Bentuk negara Indonesia adalah Negara Kesatuan (Unitary State), bukan Negara Serikat (Federal) seperti Amerika Serikat. Keputusan ini diambil oleh para pendiri bangsa (Founding Fathers) karena dianggap paling cocok untuk menyatukan masyarakat Indonesia yang sangat beragam suku, agama, ras, dan bahasanya (Bhinneka Tunggal Ika).'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam Negara Kesatuan Republik Indonesia (NKRI), kedaulatan tertinggi berada di tangan Pemerintah Pusat (yang berkedudukan di ibu kota negara). Tidak ada "negara di dalam negara". Di negara serikat, setiap negara bagian memiliki undang-undang dasar sendiri, bendera sendiri, dan kepolisian sendiri. Di Indonesia, hal itu tidak berlaku. Hanya ada satu bendera (Merah Putih), satu konstitusi (UUD 1945), satu kepala negara (Presiden), dan satu lembaga perwakilan nasional (DPR/MPR/DPD).'),
      MateriBlock(MateriBlockType.paragraph, 'Meskipun kekuasaan tertinggi ada di pusat, Indonesia sangat luas. Jika semua urusan dari Aceh sampai Papua harus diurus langsung oleh Presiden di Jakarta, prosesnya akan sangat lambat dan pembangunan menjadi tidak merata. Oleh karena itu, Indonesia menerapkan sistem'),
      MateriBlock(MateriBlockType.heading, 'Desentralisasi adalah penyerahan sebagian wewenang pemerintahan dari Pemerintah Pusat kepada Pemerintah Daerah (Provinsi, Kabupaten, dan Kota). Dari sistem ini lahirlah Otonomi Daerah.'),
      MateriBlock(MateriBlockType.bullet, 'Apa itu Otonomi Daerah? Hak, wewenang, dan kewajiban daerah otonom untuk mengatur dan mengurus sendiri urusan pemerintahan dan kepentingan masyarakat setempat sesuai dengan peraturan perundang-undangan.'),
      MateriBlock(MateriBlockType.bullet, 'Contoh Praktis: Pemerintah daerah berhak membangun sekolah, mengatur lalu lintas kota, mengembangkan pariwisata daerah, dan mengelola pendapatan daerah (APBD). Namun, ada urusan mutlak yang tidak boleh diurus daerah dan tetap dipegang pusat, yaitu: Politik Luar Negeri, Pertahanan (TNI), Keamanan (Polri), Yustisi (Hukum/Pengadilan), Moneter (Mencetak uang), dan Agama.'),
      MateriBlock(MateriBlockType.paragraph, 'Melalui otonomi daerah, setiap daerah bisa berkembang sesuai dengan potensi dan budayanya masing-masing, tanpa pernah lepas dari ikatan Negara Kesatuan Republik Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Upaya Menjaga Keutuhan Wilayah'),
      MateriBlock(MateriBlockType.paragraph, 'Menjaga keutuhan wilayah NKRI bukan hanya tugas tentara atau polisi, melainkan tanggung jawab seluruh warga negara, termasuk pelajar SMP. Ancaman terhadap keutuhan wilayah di era modern tidak hanya berupa penjajahan fisik, tetapi juga perpecahan dari dalam dan serangan non-fisik (ideologi, sosial-budaya, dan siber).'),
      MateriBlock(MateriBlockType.paragraph, 'Bentuk Ancaman terhadap Keutuhan NKRI'),
      MateriBlock(MateriBlockType.bullet, 'Ancaman Fisik/Militer: Sengketa perbatasan darat dan laut dengan negara tetangga, pencurian ikan oleh kapal asing (illegal fishing), atau gerakan separatisme (kelompok bersenjata yang ingin memisahkan diri dari Indonesia).'),
      MateriBlock(MateriBlockType.bullet, 'Ancaman Non-Fisik/Non-Militer: Penyebaran berita bohong (hoaks) yang memicu konflik antar-suku atau agama, radikalisme, tawuran pelajar, peredaran narkoba yang merusak generasi muda, dan masuknya budaya asing yang bertentangan dengan nilai Pancasila.'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai remaja yang sedang menempuh pendidikan di tingkat SMP, upaya menjaga keutuhan negara bisa dilakukan melalui tindakan sehari-hari di lingkungan rumah, sekolah, dan masyarakat:'),
      MateriBlock(MateriBlockType.bullet, 'Menerapkan Toleransi: Berteman dengan siapa saja tanpa membedakan agama, suku, atau kondisi ekonomi. Tidak melakukan perundungan (bullying) kepada teman yang berbeda.'),
      MateriBlock(MateriBlockType.bullet, 'Bijak Bermedia Sosial: Saring sebelum sharing. Tidak ikut menyebarkan berita provokatif atau ujaran kebencian di TikTok, Instagram, atau WhatsApp yang bisa memecah belah masyarakat.'),
      MateriBlock(MateriBlockType.bullet, 'Mempelajari Budaya Daerah Lain: Selain mengenal budaya sendiri, mempelajari tarian, bahasa, atau makanan dari daerah lain di Indonesia akan menumbuhkan rasa cinta pada keberagaman (Bhinneka Tunggal Ika).'),
      MateriBlock(MateriBlockType.bullet, 'Menggunakan Produk Dalam Negeri: Membeli dan bangga menggunakan barang-barang buatan Indonesia, yang secara langsung membantu perekonomian negara agar tetap kuat dan mandiri.'),
      MateriBlock(MateriBlockType.bullet, 'Disiplin dan Berprestasi: Mengikuti upacara bendera dengan khidmat untuk menghormati jasa pahlawan, rajin belajar, dan mencetak prestasi (akademik, olahraga, atau seni) untuk mengharumkan nama bangsa. Pelajar yang cerdas dan berkarakter adalah benteng terkuat untuk melindungi masa depan wilayah dan kedaulatan NKRI.'),
    ],
  ),
];
